func enemy_orders() -> Dictionary:
	var orders: Dictionary = {}
	var players: Array[Dictionary] = alive_units(PLAYER)
	for e: Dictionary in alive_units(ENEMY):
		var sees_player: bool = false
		for p: Dictionary in players:
