				break
		var guard: bool = (config["enemy_ai"] as Dictionary).get(e["id"], "march") == "guard"
		var step: Vector2i = Vector2i.ZERO if sees_player or guard else Vector2i(-1, 0)
		if not on_board(cell_of(e) + step):
			step = Vector2i.ZERO
		orders[e["id"]] = step
	return orders


